async fn resident_idle_delivery_delay_keeps_original_service_expiry_and_joins() -> anyhow::Result<()> {
    let (service, remainder, latest_original_end) = Box::pin(idle(false,
        Duration::from_secs(1), Duration::from_millis(400))).await?.split();
    let cancellation = CancellationToken::new();
    let _cancel_on_drop = cancellation.clone().drop_guard();
    let running = tokio::spawn(RootResidentCandidateServiceV1::run(service, cancellation.clone()));
