    let (handoff, after_send) = transfer(&root.profile, role_streams(&peer, streams, &root.profile, original)?)?;
    tokio::time::sleep(Duration::from_millis(100)).await;
    let (streams, end) = handoff.into_original_streams(&root.profile)?;
    assert!(end <= after_send + original, "the same absolute end must survive delivery delay");
    assert!(lifetimes(&streams).into_iter().all(|remaining| remaining < original - Duration::from_millis(80)));
    // Every returned real socket still pins the same dedicated process. This
    // does not make these deliberately idle endpoints into original role owners.
    assert_eq!(streams.common.trainer.peer.pid, peer.peer.pid);
    drop(streams);
    peer.finish()?;

    let mut peer = process::PeerProcess::start()?;
    let (streams, a) = peer.take_streams()?;
    drop(a);
    let (handoff, _) = transfer(&root.profile, role_streams(&peer, streams, &root.profile, Duration::from_millis(50))?)?;
    tokio::time::sleep(Duration::from_millis(100)).await;
    assert!(handoff.into_original_streams(&root.profile).is_err());
    peer.finish()?;
    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
