        anyhow::ensure!(case.c_has_no_new_work()?, "expiry did not execute C");
        Ok::<_, anyhow::Error>(count)
    }.await;
    let terminal = case.finish().await;
    require_closed_terminal(terminal?, result?)?;
    Ok(())
}

